-- CareLoop v0.1.0 reference schema. Demo runtime currently uses in-memory seed data.
CREATE TABLE canteens (id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL, status TEXT NOT NULL, latitude NUMERIC, longitude NUMERIC);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT UNIQUE NOT NULL, preferred_language TEXT NOT NULL DEFAULT 'zh-CN', is_elder BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE tables (id TEXT PRIMARY KEY, canteen_id TEXT NOT NULL REFERENCES canteens(id), table_number TEXT NOT NULL, area TEXT NOT NULL, capacity INTEGER NOT NULL, status TEXT NOT NULL, UNIQUE(canteen_id, table_number));
CREATE TABLE dishes (id TEXT PRIMARY KEY, canteen_id TEXT NOT NULL REFERENCES canteens(id), name TEXT NOT NULL, price_cents INTEGER NOT NULL, category TEXT NOT NULL, available BOOLEAN NOT NULL DEFAULT TRUE, allergens JSONB NOT NULL DEFAULT '[]', supported_modifiers JSONB NOT NULL DEFAULT '[]');
CREATE TABLE orders (id TEXT PRIMARY KEY, order_number TEXT UNIQUE NOT NULL, canteen_id TEXT NOT NULL REFERENCES canteens(id), created_by_user_id TEXT NOT NULL REFERENCES users(id), customer_user_id TEXT NOT NULL REFERENCES users(id), payer_user_id TEXT REFERENCES users(id), table_id TEXT NOT NULL REFERENCES tables(id), source TEXT NOT NULL, status TEXT NOT NULL, payment_method TEXT, language TEXT NOT NULL, special_instructions TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), dish_id TEXT NOT NULL REFERENCES dishes(id), dish_name_snapshot TEXT NOT NULL, unit_price_cents INTEGER NOT NULL, quantity INTEGER NOT NULL, modifiers JSONB NOT NULL DEFAULT '[]', allergen_warnings JSONB NOT NULL DEFAULT '[]');
CREATE TABLE device_tasks (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), type TEXT NOT NULL, status TEXT NOT NULL, payload JSONB NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
